import React from 'react';

function Projects() {
  const projects = [
    {
      title: 'Project Alpha',
      description: 'A comprehensive web application built for managing tasks and projects efficiently. Features real-time updates and user collaboration.',
      technologies: ['React', 'Node.js', 'Express', 'MongoDB', 'Socket.io'],
      liveLink: '#',
      githubLink: '#'
    },
    {
      title: 'Project Beta',
      description: 'An e-commerce platform with a focus on user experience and responsive design. Includes product catalog, shopping cart, and checkout process.',
      technologies: ['Next.js', 'Tailwind CSS', 'Stripe API', 'PostgreSQL'],
      liveLink: '#',
      githubLink: '#'
    },
    {
      title: 'Project Gamma',
      description: 'A personal portfolio website showcasing various design and development projects. Designed with a minimalist aesthetic and smooth animations.',
      technologies: ['React', 'Sass', 'Framer Motion'],
      liveLink: '#',
      githubLink: '#'
    },
    {
      title: 'Project Delta',
      description: 'A data visualization dashboard for analyzing sales trends. Interactive charts and graphs provide insights into business performance.',
      technologies: ['Vue.js', 'D3.js', 'Firebase'],
      liveLink: '#',
      githubLink: '#'
    }
  ];

  return (
    <section id="projects" className="py-20 bg-gray-800 text-white">
      <div className="container mx-auto px-4">
        <h2 className="text-4xl font-bold text-center mb-12 text-blue-400">My Projects</h2>
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
          {projects.map((project, index) => (
            <div key={index} className="bg-gray-900 p-6 rounded-lg shadow-lg transform hover:scale-105 transition duration-300 flex flex-col">
              <h3 className="text-2xl font-semibold mb-3 text-blue-300">{project.title}</h3>
              <p className="text-gray-300 mb-4 flex-grow">{project.description}</p>
              <div className="mb-4">
                <h4 className="text-lg font-medium mb-2">Technologies:</h4>
                <div className="flex flex-wrap gap-2">
                  {project.technologies.map((tech, techIndex) => (
                    <span key={techIndex} className="bg-gray-700 text-sm px-3 py-1 rounded-full">{tech}</span>
                  ))}
                </div>
              </div>
              <div className="flex justify-between mt-auto">
                <a
                  href={project.liveLink}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="bg-blue-600 hover:bg-blue-700 text-white font-bold py-2 px-4 rounded-full transition duration-300 text-sm"
                >
                  Live Demo
                </a>
                <a
                  href={project.githubLink}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="bg-gray-700 hover:bg-gray-600 text-white font-bold py-2 px-4 rounded-full transition duration-300 text-sm"
                >
                  GitHub
                </a>
              </div>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
}

export default Projects;
